def publish_guides(apps, schema_editor):
    alias = schema_editor.connection.alias
    User = apps.get_model("store", "User")
    Post = apps.get_model("store", "BlogPost")
    author = User.objects.using(alias).filter(is_staff=True).order_by("pk").first()
    if author is None:
        author, _ = User.objects.using(alias).get_or_create(
            username="payvict-editorial", defaults={"is_active": False, "password": "!"})
    for title, slug, content in POSTS:
        Post.objects.using(alias).get_or_create(slug=slug, defaults={
            "title": title, "content": content.strip(), "author": author, "published": True,
        })


class Migration(migrations.Migration):
    dependencies = [("store", "0023_refresh_tv_catalogue")]
    operations = [migrations.RunPython(publish_guides, migrations.RunPython.noop)]
